"""Guided-mode walkthroughs, keyed by the sim file name.

Each guide: {"controls": [one line per control], "steps": [ {do, see, check?} ]}
check = {"q", "options", "answer" (index), "why"}.
Written for students working alone: short instructions, one idea per step, a quick check before moving on.
"""

def _c(q, options, answer, why=""):
    return dict(q=q, options=options, answer=answer, why=why)


